import os, subprocess

root = "/mnt/g/VPS-K3/extracted/k3/repo"

def git(cmd):
    result = subprocess.run(
        f"cd {root} && git {cmd}",
        shell=True, capture_output=True, text=True
    )
    return result.stdout.strip() or result.stderr.strip()

def read(rel):
    full = os.path.join(root, rel)
    try:
        with open(full, encoding="utf-8", errors="replace") as f:
            return f.read()
    except Exception as e:
        return f"[ERROR: {e}]"

# Check each package's package.json
print("=== packages/ subdirs ===")
pkgs_dir = os.path.join(root, "packages")
for pkg in sorted(os.listdir(pkgs_dir)):
    pkg_json_path = os.path.join(pkgs_dir, pkg, "package.json")
    if os.path.exists(pkg_json_path):
        with open(pkg_json_path, encoding="utf-8") as f:
            import json
            try:
                data = json.load(f)
                print(f"\n  packages/{pkg}/package.json:")
                print(f"    name: {data.get('name')}")
                print(f"    version: {data.get('version')}")
                print(f"    author: {data.get('author')}")
                print(f"    license: {data.get('license')}")
                print(f"    repository: {data.get('repository')}")
                print(f"    homepage: {data.get('homepage')}")
            except:
                print(f"    [parse error]")

